        var obj = (typeof raw === 'string') ? JSON.parse(raw) : (raw || []);
        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        return reviewVerdictsModule.parseVerdictRecords(list);
    } catch (e) {
