        if (!pr || pr.message || !pr.head || !pr.head.sha) return null;
        return {
            headSha: pr.head.sha,
            labels: (pr.labels || []).map(function(l) { return (l && l.name) || l; })
        };
    } catch (e) {
        console.warn('  ⚠️ verdict probe: PR read failed (fail-open): ' + (e.message || e));
        return null;
    }
