                workspace: repoInfo.owner, repository: repoInfo.repo,
                number: ticket.prNumber, body: decision.comment
            });
        } catch (eC) {
            console.warn('  ⚠️ reconciliation comment failed (labels already reconciled): ' + (eC.message || eC));
        }
